lynx.script:
const days = [
  {
    number: "01",
    tab: "湖光",
    eyebrow: "DAY 01 · 湖光初见",
    title: "西湖慢游",
    subtitle: "沿着白堤与苏堤，把第一天交给湖风和日落。",
    distance: "约 11.8 km",
    rhythm: "轻松漫步",
    tip: "音乐喷泉场次会随季节调整；若想坐船，可在花港观鱼附近灵活加入约 40 分钟的游船体验。",
    items: [
      {
        time: "09:00",
        duration: "2 小时",
        place: "断桥残雪 · 白堤",
        detail: "从北山街进入西湖，沿白堤慢慢走到孤山，晨光和人流都更温柔。",
      },
      {
        time: "11:30",
        duration: "午餐",
        place: "孤山 · 浙江博物馆",
        detail: "在孤山附近吃杭帮菜，饭后看一场小展，为下午的长走留足体力。",
      },
      {
        time: "14:30",
        duration: "3 小时",
        place: "曲院风荷 · 苏堤",
        detail: "从曲院风荷一路向南，经过花港观鱼，在梧桐影里完成西湖经典线。",
      },
      {
        time: "18:30",
        duration: "日落",
        place: "湖滨 · 音乐喷泉",
        detail: "在湖滨等一场金色日落，晚餐后用喷泉与城市夜景结束第一天。",
      },
    ],
  },
  {
    number: "02",
    tab: "茶山",
    eyebrow: "DAY 02 · 山寺茶香",
    title: "灵隐与龙井",
    subtitle: "从千年古刹走进茶山，把城市的喧闹留在身后。",
    distance: "约 9.6 km",
    rhythm: "登高寻幽",
    tip: "灵隐景区建议早点出发；九溪步道路面湿滑时，穿防滑运动鞋，并为龙井村到九溪预留机动时间。",
    items: [
      {
        time: "08:00",
        duration: "3 小时",
        place: "灵隐寺 · 飞来峰",
        detail: "避开午后客流，在石刻与古木之间慢走，感受北高峰脚下的清幽。",
      },
      {
        time: "11:30",
        duration: "午餐",
        place: "天竺路 · 素面小馆",
        detail: "沿天竺路找一碗清爽素面，短暂休息后再前往茶山。",
      },
      {
        time: "14:00",
        duration: "3 小时",
        place: "龙井村 · 九溪烟树",
        detail: "从茶园高处走向九溪，沿溪水与杉林下行，遇见杭州最松弛的绿色。",
      },
      {
        time: "18:30",
        duration: "晚餐",
        place: "河坊街 · 南宋御街",
        detail: "回到老城吃葱包桧和定胜糕，在青石板路上散步消食。",
      },
    ],
  },
  {
    number: "03",
    tab: "宋韵",
    eyebrow: "DAY 03 · 运河宋韵",
    title: "古今杭城",
    subtitle: "沿大运河读城市肌理，再去吴山收下一场告别日落。",
    distance: "约 8.4 km",
    rhythm: "人文漫游",
    tip: "德寿宫与部分博物馆可能需要提前预约；若遇闭馆，可把下午替换为胡雪岩故居与十五奎巷。",
    items: [
      {
        time: "09:00",
        duration: "2 小时",
        place: "拱宸桥 · 运河博物馆",
        detail: "从拱宸桥看船只往来，沿桥西历史街区认识因运河而生的杭州。",
      },
      {
        time: "11:30",
        duration: "午餐",
        place: "小河直街",
        detail: "在白墙黛瓦之间找一间临河小店，留一点时间给手作铺与旧码头。",
      },
      {
        time: "14:30",
        duration: "2 小时",
        place: "南宋德寿宫遗址博物馆",
        detail: "从红墙与遗址中读南宋临安，理解杭州温柔表象下的历史厚度。",
      },
      {
        time: "17:30",
        duration: "日落",
        place: "吴山城隍阁 · 鼓楼",
        detail: "登高回望西湖与老城，在鼓楼附近吃最后一顿杭帮菜，结束三日旅程。",
      },
    ],
  },
];

const page = __CreatePage("0", 0);
const pageId = __GetElementUniqueID(page);
const engine = lynx.getEngine();
const backgroundThread = lynx.getJSContext();
const elementListeners = [];
const tabNodes = [];
let activeDayIndex = 0;
let daySlot;
let rendered = false;

__SetClasses(page, "page");

Object.assign(globalThis, {
  processData(data) {
    return data;
  },
});

function createView(className) {
  const node = __CreateView(pageId);
  __SetClasses(node, className);
  return node;
}

function createText(className, value) {
  const node = __CreateText(pageId);
  __SetClasses(node, className);
  __AppendElement(node, __CreateRawText(value));
  return node;
}

function append(parent, child) {
  __AppendElement(parent, child);
  return child;
}

function bindTap(node, handler) {
  const options = {};
  __AddEventListener(node, "tap", handler, options);
  elementListeners.push({ node, name: "tap", handler, options });
}

function createHero() {
  const hero = createView("hero");
  append(hero, createView("hero-orb hero-orb-large"));
  append(hero, createView("hero-orb hero-orb-small"));
  append(hero, createView("hero-grid-line"));

  const top = append(hero, createView("hero-top"));
  append(top, createText("hero-kicker", "CITY ESCAPE · 03 DAYS"));
  const badge = append(top, createView("hero-badge"));
  append(badge, createView("hero-badge-dot"));
  append(badge, createText("hero-badge-text", "杭州 HANGZHOU"));

  const main = append(hero, createView("hero-main"));
  const copy = append(main, createView("hero-copy"));
  append(copy, createText("hero-location", "30.2741° N · 120.1551° E"));
  append(copy, createText("hero-title", "山水入城\n三日漫游"));
  append(copy, createText("hero-subtitle", "湖光、茶山与宋韵\n一份留有呼吸感的杭州路线"));
  append(main, createText("hero-day-mark", "03"));

  const stats = append(hero, createView("hero-stats"));
  const statOne = append(stats, createView("hero-stat"));
  append(statOne, createText("hero-stat-value", "3 DAYS"));
  append(statOne, createText("hero-stat-label", "行程天数"));
  const statTwo = append(stats, createView("hero-stat hero-stat-center"));
  append(statTwo, createText("hero-stat-value", "12 STOPS"));
  append(statTwo, createText("hero-stat-label", "精选停靠"));
  const statThree = append(stats, createView("hero-stat hero-stat-last"));
  append(statThree, createText("hero-stat-value", "29.8 KM"));
  append(statThree, createText("hero-stat-label", "建议步行"));
  return hero;
}

function createTabs() {
  const section = createView("tabs-section");
  append(section, createText("tabs-label", "SELECT YOUR DAY"));
  const tabs = append(section, createView("day-tabs"));

  days.forEach((day, index) => {
    const tab = append(tabs, createView(index === activeDayIndex ? "day-tab active" : "day-tab"));
    __SetAttribute(tab, "aria-label", "查看第 " + String(index + 1) + " 天行程：" + day.tab);
    append(tab, createText("day-tab-number", "DAY " + String(index + 1)));
    append(tab, createText("day-tab-name", day.tab));
    append(tab, createView("day-tab-dot"));
    bindTap(tab, () => selectDay(index));
    tabNodes.push(tab);
  });

  return section;
}

function createDayMeta(day) {
  const meta = createView("day-meta");
  const distance = append(meta, createView("day-meta-item"));
  append(distance, createText("day-meta-icon", "⌁"));
  append(distance, createText("day-meta-text", day.distance));
  const rhythm = append(meta, createView("day-meta-item day-meta-item-last"));
  append(rhythm, createText("day-meta-icon", "◷"));
  append(rhythm, createText("day-meta-text", day.rhythm));
  return meta;
}

function createRouteItem(item, isLast) {
  const row = createView("route-item");
  const rail = append(row, createView("route-rail"));
  append(rail, createView("route-dot"));
  append(rail, createView(isLast ? "route-line route-line-last" : "route-line"));

  const card = append(row, createView("route-card"));
  const topline = append(card, createView("route-topline"));
  append(topline, createText("route-time", item.time));
  append(topline, createText("route-duration", item.duration));
  append(card, createText("route-place", item.place));
  append(card, createText("route-detail", item.detail));
  return row;
}

function createTip(day) {
  const tip = createView("tip-card");
  append(tip, createText("tip-icon", "✦"));
  const copy = append(tip, createView("tip-copy"));
  append(copy, createText("tip-title", "出发前的小提示"));
  append(copy, createText("tip-text", day.tip));
  return tip;
}

function createDayPanel(day) {
  const panel = createView("day-panel");
  const heading = append(panel, createView("day-heading"));
  const numberBox = append(heading, createView("day-number-box"));
  append(numberBox, createText("day-number", day.number));
  const headingCopy = append(heading, createView("day-heading-copy"));
  append(headingCopy, createText("day-eyebrow", day.eyebrow));
  append(headingCopy, createText("day-title", day.title));
  append(headingCopy, createText("day-subtitle", day.subtitle));
  append(panel, createDayMeta(day));

  const routeList = append(panel, createView("route-list"));
  day.items.forEach((item, index) => {
    append(routeList, createRouteItem(item, index === day.items.length - 1));
  });
  append(panel, createTip(day));
  return panel;
}

function updateTabs() {
  tabNodes.forEach((tab, index) => {
    __SetClasses(tab, index === activeDayIndex ? "day-tab active" : "day-tab");
  });
}

function selectDay(index) {
  if (index === activeDayIndex) {
    return;
  }
  activeDayIndex = index;
  updateTabs();
  __ReplaceElements(daySlot, [createDayPanel(days[index])], __GetChildren(daySlot));
  __FlushElementTree();
}

function createFooter() {
  const footer = createView("footer");
  append(footer, createText("footer-mark", "HANGZHOU · 杭州"));
  append(footer, createText("footer-text", "把城市留给步行，把日落留给西湖"));
  return footer;
}

function renderPage() {
  if (rendered) {
    return;
  }
  rendered = true;
  const scroll = __CreateScrollView(pageId);
  __SetClasses(scroll, "page-scroll");
  __SetAttribute(scroll, "scroll-orientation", "vertical");
  __SetAttribute(scroll, "scroll-bar-enable", false);
  append(page, scroll);

  const shell = append(scroll, createView("app-shell"));
  const card = append(shell, createView("trip-card"));
  append(card, createHero());
  const content = append(card, createView("content"));
  append(content, createTabs());
  daySlot = append(content, createView("day-slot"));
  append(daySlot, createDayPanel(days[activeDayIndex]));
  append(content, createFooter());
}

function onRenderPage() {
  renderPage();
}

function cleanup() {
  const currentListeners = elementListeners.splice(0);
  currentListeners.forEach((listener) => {
    __RemoveEventListener(
      listener.node,
      listener.name,
      listener.handler,
      listener.options,
    );
  });
  engine.removeEventListener("__RenderPage", onRenderPage);
  engine.removeEventListener("__DestroyLifetime", cleanup);
  backgroundThread.dispatchEvent({
    type: "__DestroyLifetime",
    data: undefined,
  });
  tabNodes.splice(0);
  daySlot = undefined;
}

engine.addEventListener("__RenderPage", onRenderPage);
engine.addEventListener("__DestroyLifetime", cleanup);

const mainThread = lynx.getCoreContext();

function cleanupBackground() {
  mainThread.removeEventListener("__DestroyLifetime", cleanupBackground);
}

mainThread.addEventListener("__DestroyLifetime", cleanupBackground);
